	private void Update() {
		if (startTrackingStartingPoint) {
			Vector3 rayOrigin = Camera.main.transform.position;
			Vector3 rayDirection = Vector3.down;
			if (Physics.Raycast(rayOrigin, rayDirection, out RaycastHit hit, Mathf.Infinity, startingPointLayer)) {
				outOfPointWarningPanel.SetActive(false);
				if (!isStepInForTheFirstTime) {
					QrScanned("P3-201C");
					isStepInForTheFirstTime = true;
				}
			}
		} else {
			outOfPointWarningPanel.SetActive(false);
		}
	}

	private void SwitchPanel(int direction) {
		if (eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count == 0) return;
		currentIndex += direction;
		if (currentIndex >= eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count) {
			currentIndex = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count - 1;
		} else if (currentIndex < 0) {
			currentIndex = 0;
		}
		DisplayPanel(currentIndex);
		UpdateButtonStates(currentIndex, eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count);
	}

	public void DisplayPanel(int index) {
		if (eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url != null && eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url != "") {
			if (previousVideoString != eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url) {
				previousVideoString = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url;
				stepByStepGuidePanelWithVideo.gameObject.SetActive(true);
				//videoPlayerScaleablePanel.gameObject.SetActive(true);
				videoPlayer.url = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url;
				//videoPlayerScaleablePanel.url = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[index].blob_url;
				videoPlayer.Play();
			}
			if (currentIndex != 0) {
				//videoPlayerScaleablePanel.Play();
				handCoachControl.MoveAnimation(step2EndingPosition, 2, () => handCoachControl.MoveAnimation(step2InitialPosition, 2, StartLoop2));
			} else {
				//videoPlayerScaleablePanel.Pause();
				//videoPlayerScaleablePanel.frame = 0;
				handCoachControl.MoveAnimation(step1EndingPosition, 2, () => handCoachControl.MoveAnimation(step1InitialPosition, 2, StartLoop1));
			}
		} else {
			stepByStepGuidePanelWithVideo.gameObject.SetActive(false);
			//videoPlayerScaleablePanel.gameObject.SetActive(false);
		}

		//stepByStepGuideVideoText_HeaderTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[currentIndex].title;
		stepByStepGuideVideoText_HeaderTextField.text = (currentIndex + 1).ToString();
		stepByStepGuideVideoText_TextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[currentIndex].message;
		UpdateButtonStates(currentIndex, eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count);
	}

	public override void AssignETaskInstruction(DownloadHandler returnedItems) {
		base.AssignETaskInstruction(returnedItems);
		currentIndex = 0;
		//UpdateButtonStates(currentIndex, eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count);
		for (int i = 0; i < eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Count - 1; i++) {
			switch (i) {
				default:
				GameObject item = Instantiate(stepByStepGuideTextItemPrefab, guideItemHolder);
				StepByStepGuideTextItem itemScript = item.GetComponent<StepByStepGuideTextItem>();
				itemScript.descriptionTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].message;
				break;
				case 0:
				GameObject item3 = Instantiate(stepByStepGuideTextItemPrefab, guideItemHolder);
				StepByStepGuideTextItem itemScript3 = item3.GetComponent<StepByStepGuideTextItem>();
				itemScript3.descriptionTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].message;
				RectTransform item3RectTransform = item3.GetComponent<RectTransform>();
				Vector2 size = item3RectTransform.sizeDelta;
				size.y = 7;
				item3RectTransform.sizeDelta = size;
				break;
				case 1:
				GameObject item2 = Instantiate(StepByStepGuideTextAndVideoItemPrefab, guideItemHolder);
				StepByStepGuideTextAndVideoItem itemScript2 = item2.GetComponent<StepByStepGuideTextAndVideoItem>();
				itemScript2.descriptionTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].message;
				itemScript2.videoPlayer.url = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].blob_url;
				itemScript2.videoPlayer.Play();
				RectTransform item2RectTransform = item2.GetComponent<RectTransform>();
				Vector2 size2 = item2RectTransform.sizeDelta;
				size2.y = 70;
				item2RectTransform.sizeDelta = size2;
				RectTransform videoPlayerRectTransform = itemScript2.videoPlayer.GetComponent<RectTransform>();
				Vector2 videoPosition = videoPlayerRectTransform.anchoredPosition;
				videoPosition.y = -3;
				videoPlayerRectTransform.anchoredPosition = videoPosition;
				break;
			}
		}
	}

	public void AssignEquipment(DownloadHandler returnedItems) {
		string wrappedJson = "{ \"equipmentResponse\": " + returnedItems.text + " }";
		EquipmentResponseWrapper wrapper = JsonUtility.FromJson<EquipmentResponseWrapper>(wrappedJson);

		if (wrapper != null && wrapper.equipmentResponse != null) {
			equipmentResponseWrapper = wrapper;
		}

		pumpNoText.text = "Pump No: " + equipmentResponseWrapper.equipmentResponse[0].equipment_id;
		pumpNoText2.text = "Pump No: " + equipmentResponseWrapper.equipmentResponse[0].equipment_id;
		switch (equipmentResponseWrapper.equipmentResponse[0].equipment_status_color) {
			case "green":
			statusImage.sprite = greenLight;
			break;
			default:
			statusImage.sprite = yellowLight;
			break;
		}
		switch (equipmentResponseWrapper.equipmentResponse[0].equipment_parameter_color) {
			case "green":
			equipmentLight.sprite = greenLight;
			break;
			default:
			equipmentLight.sprite = yellowLight;
			break;
		}

		pressureGraph.SetUpGraphData(equipmentResponseWrapper.equipmentResponse[0].pressure_uom, equipmentResponseWrapper.equipmentResponse[0].pressure.ToList());
		pressureGraph.StartRunningGraph();

		temperatureGraph.SetUpGraphData(equipmentResponseWrapper.equipmentResponse[0].temperature_uom, equipmentResponseWrapper.equipmentResponse[0].temperature.ToList());
		temperatureGraph.StartRunningGraph();

		flowRateGraph.SetUpGraphData(equipmentResponseWrapper.equipmentResponse[0].flowrate_uom, equipmentResponseWrapper.equipmentResponse[0].flowrate.ToList());
		flowRateGraph.StartRunningGraph();

		motorSpdGraph.SetUpGraphData(equipmentResponseWrapper.equipmentResponse[0].motor_speed_uom, equipmentResponseWrapper.equipmentResponse[0].motor_speed.ToList());
		motorSpdGraph.StartRunningGraph();


		byte[] imageBytes = Convert.FromBase64String(equipmentResponseWrapper.equipmentResponse[0].base64_img);
		Texture2D texture = new Texture2D(2, 2);
		texture.LoadImage(imageBytes);
		machineSprite.sprite = Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(0.5f, 0.5f)); ;
		statusText.text = "Status: " + equipmentResponseWrapper.equipmentResponse[0].equipment_status;
		pumpNameText.text = "Pump Name: " + equipmentResponseWrapper.equipmentResponse[0].equipment_name;
		pumpNameText2.text = "Pump Name: " + equipmentResponseWrapper.equipmentResponse[0].equipment_name;

		InvokeRepeating("DisplayNextValue", 0f, 0.5f);

		infoPanel1.SetActive(true);
		stepByStepGuidePanelParentObj.SetActive(true);
		//DisplayPanel(0);
		stepByStepGuidePanelWithScrollView.SetActive(true);
		verifyAMPMeterButton.button.gameObject.SetActive(true);
		//completeButton.button.transform.parent = guideItemHolder.transform;
	}

	int currentPressureReadingIndex = 0;
	int currentTemperatureReadingIndex = 0;
	int currentFlowrateReadingIndex = 0;
	int currentMotorSpeedReadingIndex = 0;

	void DisplayNextValue() {
		if (equipmentResponseWrapper.equipmentResponse.Count <= 0) return;
		pressureText.text = "Pressure: " + equipmentResponseWrapper.equipmentResponse[0].pressure[currentPressureReadingIndex].ToString() + " " + equipmentResponseWrapper.equipmentResponse[0].pressure_uom;
		temperatureText.text = "Temperature: " + equipmentResponseWrapper.equipmentResponse[0].temperature[currentTemperatureReadingIndex].ToString() + " " + equipmentResponseWrapper.equipmentResponse[0].temperature_uom;
		flowrateText.text = "Flowrate: " + equipmentResponseWrapper.equipmentResponse[0].flowrate[currentFlowrateReadingIndex].ToString() + " " + equipmentResponseWrapper.equipmentResponse[0].flowrate_uom;
		MotorSpeedText.text = "Motorspeed: " + equipmentResponseWrapper.equipmentResponse[0].motor_speed[currentMotorSpeedReadingIndex].ToString() + " " + equipmentResponseWrapper.equipmentResponse[0].motor_speed_uom;
		currentPressureReadingIndex++;  // Move to the next element in the array
		currentTemperatureReadingIndex++;
		currentFlowrateReadingIndex++;
		currentMotorSpeedReadingIndex++;
		if (currentPressureReadingIndex >= equipmentResponseWrapper.equipmentResponse[0].pressure.Length) {
			currentPressureReadingIndex = 0;
		}
		if (currentTemperatureReadingIndex >= equipmentResponseWrapper.equipmentResponse[0].temperature.Length) {
			currentTemperatureReadingIndex = 0;
		}
		if (currentFlowrateReadingIndex >= equipmentResponseWrapper.equipmentResponse[0].flowrate.Length) {
			currentFlowrateReadingIndex = 0;
		}
		if (currentMotorSpeedReadingIndex >= equipmentResponseWrapper.equipmentResponse[0].motor_speed.Length) {
			currentMotorSpeedReadingIndex = 0;
		}
	}

	void TaskComplete() {
		isStepInForTheFirstTime = false;
		var queryParamsGetUserAttributes = new Dictionary<string, string> {
			{"user_id",  pageManager.managerControlScript.loginScript.userAccountDetails.user_id.ToString() }
			};
		ApiManager.instance.APICallGETWithParameters(
		APIGetMiddlePath.APIGetMiddlePathList[(int)APIGetMiddlePathEnum.UserAttributes],
		queryParamsGetUserAttributes,
		() => { },
		(DownloadHandler downloadHandler) => {
			pageManager.managerControlScript.loginScript.ProcessGetUserAttributesResponse(downloadHandler);
			pageManager.homePagePanel.UpdateTaskCount.Invoke();
			pageManager.homePagePanel.homePanel.SetActive(true);
		});
		pageManager.handMenuPanelsManager.stillCanShowMoreOptionDetails = true;
	}

	public void QrScanned(string qrCodeString) {
		nextStepButtonImageTextPanel.button.enabled = true;
		nextStepButtonTextPanel.button.enabled = true;
		nextStepButtonVideoTextPanel.button.enabled = true;
		previousStepButtonImageTextPanel.button.enabled = true;
		previousStepButtonTextPanel.button.enabled = true;
		previousStepButtonVideoTextPanel.button.enabled = true;
		verifyAMPMeterButton.button.enabled = true;
		startTrackingStartingPoint = false;
		guideStartingPoint.SetActive(false);
		guideStartingPointCollider.enabled = false;
		var queryParamEquipments = new Dictionary<string, string> {
							{"equipment_id", qrCodeString},
						};
		ApiManager.instance.APICallGETWithParameters(
			APIGetMiddlePath.APIGetMiddlePathList[(int)APIGetMiddlePathEnum.Equipment],
			queryParamEquipments,
			() => {
			},
			AssignEquipment
			);
		ApiManager.instance.APICallGETWithParameters(
			APIGetMiddlePath.APIGetMiddlePathList[(int)APIGetMiddlePathEnum.EquipmentIncidents],
			queryParamEquipments,
			() => { },
			pageManager.cautionPanelPumpShutdown.AssignequipmentIncidents
			);
	}

	#region Photo Taking
	void PhotoTaken(ActiveValidations parameters) {
		if (pageManager.managerControlScript.loginScript.playerType != PlayerType.FO) return;

		//string[] imageArray = { meterT1Sample, meterT1FocusSample, meterT2IgnoreSample, meterT2Sample, meterT2FocusSample, parameters.base64_image };
		string[] imageArray = { meter1Sample, meter2Sample, parameters.base64_image };
		ActiveValidationsOpenaiMultiple parametersWithMultipleImages = new ActiveValidationsOpenaiMultiple(
			pageManager.cameraPanel.currentPhotoMessageInput,
			imageArray
		);
		string jsonDataActiveValidation = JsonUtility.ToJson(parametersWithMultipleImages);

		//string[] imageAr	ray = { meterT1Sample, meterT1FocusSample, meterT2IgnoreSample, meterT2Sample, meterT2FocusSample, parameters.base64_image };
		//ActiveValidationsOpenaiMultiple parametersWithMultipleImages = new ActiveValidationsOpenaiMultiple(
		//	pageManager.cameraPanel.currentPhotoMessageInput,
		//	imageArray
		//);
		//string jsonDataActiveValidation = JsonUtility.ToJson(parametersWithMultipleImages);
		Debug.Log($"Pump Shutdown, Sending Data To OpenAI: {pageManager.cameraPanel.currentPhotoMessageInput}");
		Debug.Log($"Result Photo: {parameters.base64_image}");
		StartCoroutine(
			ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenaiMultiple],
			jsonDataActiveValidation,
			() => {
			},
			CheckPhoto
			));
	}

	void CheckPhoto(DownloadHandler returnedItems) {
		pumpShutdownValidationResponse = JsonUtility.FromJson<PumpShutdownValidation>(returnedItems.text);
		pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
		Debug.Log($"Pump Shutdown, Result Received From OpenAI: {returnedItems.text}");
		if (pumpShutdownValidationResponse != null) {
			if (pumpShutdownValidationResponse.isMeterDetected) {
				if (pumpShutdownValidationResponse.meterType1_or_meterType2_or_undefined.ToLower() == "undefined") {
					AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
					pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
					pageManager.aiValidationPanel.aiValidateDetailsText.text = "Invalid meter type";
					StartCoroutine(StartCountdown(5, () => {
						pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
					}));
				} else {
					//if (pumpShutdownValidationResponse.amp_meter_reading <= 0) {
					if (pumpShutdownValidationResponse.isAtLeftMost || pumpShutdownValidationResponse.amp_meter_reading <= 0) {
						pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Successful";
						pageManager.aiValidationPanel.aiValidateDetailsText.text = "Ammeter Reading: 0";
						AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationSuccessSfx);
						StartCoroutine(StartCountdown(5, () => {
							completePanel.SetActive(true);
							bigTitleText1.text = "Pump P3-201C";
							bigTitleText2.text = "Successfully Shut Down";
							smallDetailsText.text = "Electrician has been notified";
							pageManager.cameraPanel.takePhotoButton.button.enabled = false;
							pageManager.cameraPanel.cameraPanel.SetActive(false);
							pageManager.cameraPanel.StopAutoTakePhotoForActiveValidation();
							stepByStepGuidePanelWithScrollView.SetActive(false);
							verifyAMPMeterButton.button.gameObject.SetActive(false);
							StartCountdownAfterCompleted();
							//completeButton.button.transform.parent = stepByStepGuidePanelParentObj.transform;
						}));
					} else {
						AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
						pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
						pageManager.aiValidationPanel.aiValidateDetailsText.text = "Ammeter Reading: " + pumpShutdownValidationResponse.amp_meter_reading;
						StartCoroutine(StartCountdown(5, () => {
							pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
						}));
					}
				}
			} else {
				AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "No meter detected";
				StartCoroutine(StartCountdown(5, () => {
					pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
				}));
			}

		} else {
			pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
			pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
			pageManager.aiValidationPanel.aiValidateDetailsText.text = "No Data";
			AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
			StartCoroutine(StartCountdown(5, () => {
				pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
			}));
		}
	}
	#endregion

	protected override void PerformActionAfterCompleteTaskCountdown() {
		base.PerformActionAfterCompleteTaskCountdown();
		StopCountdown();
		pageManager.cautionPanelPumpShutdown.cautionPanel.SetActive(false);
		stepByStepGuidePanelParentObj.SetActive(false);
		infoPanel1.SetActive(false);
		infoPanel3.SetActive(false);
		infoPanel2.SetActive(false);
		completePanel.SetActive(false);
		previousVideoString = "";
		videoPlayerScaleablePanel.gameObject.SetActive(false);
		string jsonDataEditJobPack = JsonUtility.ToJson(new ETaskStatus(pageManager.specificETaskPanel.taskNumber, "Completed", pageManager.specificETaskPanel.taskOrderNumber));
		StartCoroutine(ApiManager.instance.APICallPut(
			APIPutMiddlePath.APIPutMiddlePathList[(int)APIPutMiddlePathEnum.ETaskStatus],
			jsonDataEditJobPack,
			() => {
				TaskComplete();
			}
		));
	}

	protected override void UpdateButtonStates(int currentIndex, int maxIndex) {
		previousStepButtonTextPanel.button.gameObject.SetActive(currentIndex > 0);
		previousStepButtonImageTextPanel.button.gameObject.SetActive(currentIndex > 0);
		previousStepButtonVideoTextPanel.button.gameObject.SetActive(currentIndex > 0);

		nextStepButtonTextPanel.button.gameObject.SetActive(currentIndex < maxIndex - 2);
		nextStepButtonImageTextPanel.button.gameObject.SetActive(currentIndex < maxIndex - 2);
		nextStepButtonVideoTextPanel.button.gameObject.SetActive(currentIndex < maxIndex - 2);
		//completeButtonTextPanel.button.gameObject.SetActive(currentIndex == maxIndex - 2);
		//completeButtonImageTextPanel.button.gameObject.SetActive(currentIndex == maxIndex - 2);
		//completeButtonVideoTextPanel.button.gameObject.SetActive(currentIndex == maxIndex - 2);

		verifyAMPMeterButton.button.gameObject.SetActive(currentIndex == maxIndex - 2);
	}

	public override void LogoutCalled() {
		base.LogoutCalled();
		stepByStepGuidePanelParentObj.SetActive(false);
		infoPanel1.SetActive(false);
		infoPanel3.SetActive(false);
		infoPanel2.SetActive(false);
		completePanel.SetActive(false);
		videoPlayerScaleablePanel.gameObject.SetActive(false);

		startTrackingStartingPoint = false;
		guideStartingPoint.SetActive(false);
		guideStartingPointCollider.enabled = false;

		eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Clear();
		equipmentResponseWrapper.equipmentResponse.Clear();
		activeValidationResponse.Validated = "";
		previousVideoString = "";
	}

	public override void UIInteractable(bool interactableStatus) {
		base.UIInteractable(interactableStatus);
		verifyAMPMeterButton.button.enabled = interactableStatus;
		showInfoPanelOtherInfoPanel.button.enabled = interactableStatus;
		showInfoPanel1.button.enabled = interactableStatus;
		completeButton.button.enabled = interactableStatus;
	}

	private void StartLoop1() {
		handCoachControl.MoveAnimation(step1EndingPosition, 2, () => handCoachControl.MoveAnimation(step1InitialPosition, 2, StartLoop1));
	}

	private void StartLoop2() {
		handCoachControl.MoveAnimation(step2EndingPosition, 2, () => handCoachControl.MoveAnimation(step2InitialPosition, 2, StartLoop2));
	}

	private void PPEStatus(bool status) {
		if (!status) return;
		pageManager.callPanel.callPanelText.text = "Please call the panel man to check if the Backup pump is up and running";
		pageManager.PanelActivation(pageManager.callPanel.callPanel);
		pageManager.callPanel.StartCountdown();
	}
}

