public enum MeterType {
	Undefined,
	Type1,
	Type2,
}

[Serializable]
public class PumpShutdownValidation {
	public bool isMeterDetected;
	public string meterType1_or_meterType2_or_undefined;
	public bool isAtLeftMost;
	public float amp_meter_reading;
}